from openpyxl import load_workbook
from openpyxl.cell.cell import Cell
import string

def generate_urn(base_number, count):
    # Convert the count to a base-26 "number" using letters a-z
    letters = []
    while count > 0:
        count, remainder = divmod(count - 1, 26)
        letters.append(string.ascii_lowercase[remainder])
    return f"{base_number}{''.join(reversed(letters))}"

def main():
    # Load the workbook
    workbook = load_workbook("input.xlsx")
    sheet = workbook["Sheet1"]

    # Iterate through the rows in column A
    for row in sheet.iter_rows(min_col=1, max_col=1):
        cell: Cell = row[0]
        if cell.row == 1:
            continue  # Skip the header row

        # Check if the cell is blank
        if not cell.value:
            # Find the last non-blank cell above this one
            last_urn_cell = None
            for r in range(cell.row - 1, 0, -1):
                urn_cell = sheet.cell(row=r, column=1)
                if urn_cell.value:
                    last_urn_cell = urn_cell
                    break

            if last_urn_cell:
                # Extract the base number from the last URN
                base_number = None
                for c in last_urn_cell.value:
                    if c.isdigit():
                        base_number = int(c)
                    else:
                        break

                # Count the number of blank cells since the last URN
                blank_count = 0
                for r in range(last_urn_cell.row + 1, cell.row):
                    if not sheet.cell(row=r, column=1).value:
                        blank_count += 1

                # Generate the new URN
                new_urn = generate_urn(base_number, blank_count + 1)
                cell.value = new_urn

    # Save the workbook
    workbook.save("output.xlsx")

if __name__ == "__main__":
    main()
