from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Dictionary to track which projects include technology
projects_with_technology = {}

# First pass: identify projects that include technology
for row in ws.iter_rows(min_row=2, max_col=17, values_only=True):
    _, _, _, _, _, _, _, project_id, _, budget_id, _, _, _, _, _, technology_revenue, _ = row
    if project_id and budget_id:
        if technology_revenue > 0:
            projects_with_technology[budget_id] = True

# Second pass: mark all lines of projects that include technology
for row in ws.iter_rows(min_row=2, max_col=17):
    _, _, _, _, _, _, _, project_id, _, budget_id, _, _, _, _, _, _, _ = row
    cell = row[16]  # Column Q (index 16)

    if project_id and budget_id:
        if budget_id in projects_with_technology:
            cell.value = "Y"
        else:
            cell.value = "N"
    else:
        cell.value = "N"

# Save the workbook as output.xlsx
wb.save("output.xlsx")
