from openpyxl import load_workbook
from datetime import datetime, timedelta
import math

# Load the workbook
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Get the year from row 11, column 14 (the last year in the header)
year = int(ws["N11"].value)

# Define the months (1 to 12)
months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

# Function to calculate the number of days in a month (considering leap years)
def days_in_month(year, month):
    if month == 12:
        return 31
    elif month == 11:
        return 30
    elif month == 10:
        return 31
    elif month == 9:
        return 30
    elif month == 8:
        return 31
    elif month == 7:
        return 31
    elif month == 6:
        return 30
    elif month == 5:
        return 31
    elif month == 4:
        return 30
    elif month == 3:
        return 31
    elif month == 2:
        # Check for leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        else:
            return 28
    elif month == 1:
        return 31
    else:
        return 0

# Function to format the number according to the rules
def format_number(value):
    if value == 0:
        return 0
    elif value - math.floor(value) == 0:
        return int(value)
    elif value - math.floor(value) == 0.1 or value - math.floor(value) == 0.9:
        return round(value, 1)
    else:
        return round(value, 9)

# Calculate the percentage of night shifts for the given year
for i, month in enumerate(months):
    # Find the column index for the current month
    col = chr(ord("B") + i)

    # Get the number of night shifts for the current month
    night_shifts = int(ws[f"{col}9"].value)

    # Calculate the number of days in the current month
    total_days = days_in_month(year, i + 1)

    # Calculate the percentage of night shifts
    if total_days == 0:
        percentage = 0
    else:
        percentage = night_shifts / total_days

    # Format the percentage
    formatted_percentage = format_number(percentage)

    # Write the result to the corresponding cell in row 11
    ws[f"{col}11"].value = formatted_percentage

# Save the workbook
wb.save("output.xlsx")
